1	package org.jsoup.select;
2	
3	import org.jsoup.helper.Validate;
4	import org.jsoup.nodes.Element;
5	import org.jsoup.nodes.LeafNode;
6	import org.jsoup.nodes.Node;
7	import org.jsoup.nodes.TextNode;
8	import org.jspecify.annotations.Nullable;
9	
10	import java.util.stream.Collectors;
11	import java.util.stream.Stream;
12	
13	import static java.util.stream.Collectors.toCollection;
14	
15	/**
16	 * Collects a list of elements that match the supplied criteria.
17	 *
18	 * @author Jonathan Hedley
19	 */
20	public class Collector {
21	
22	    private Collector() {}
23	
24	    /**
25	     Build a list of elements, by visiting the root and every descendant of root, and testing it against the Evaluator.
26	     @param eval Evaluator to test elements against
27	     @param root root of tree to descend
28	     @return list of matches; empty if none
29	     */
30	    public static Elements collect(Evaluator eval, Element root) {
31	        Stream<Element> stream = eval.wantsNodes() ?
32	            streamNodes(eval, root, Element.class) :
33	            stream(eval, root);
34	        Elements els = stream.collect(toCollection(Elements::new));
35	        eval.reset(); // drops any held memos
36	        return els;
37	    }
38	
39	    /**
40	     Obtain a Stream of elements by visiting the root and every descendant of root and testing it against the evaluator.
41	
42	     @param evaluator Evaluator to test elements against
43	     @param root root of tree to descend
44	     @return A {@link Stream} of matches
45	     @since 1.19.1
46	     */
47	    public static Stream<Element> stream(Evaluator evaluator, Element root) {
48	        evaluator.reset();
49	        return root.stream().filter(evaluator.asPredicate(root));
50	    }
51	
52	    /**
53	     Obtain a Stream of nodes, of the specified type, by visiting the root and every descendant of root and testing it
54	     against the evaluator.
55	
56	     @param evaluator Evaluator to test elements against
57	     @param root root of tree to descend
58	     @param type the type of node to collect (e.g. {@link Element}, {@link LeafNode}, {@link TextNode} etc)
59	     @param <T> the type of node to collect
60	     @return A {@link Stream} of matches
61	     @since 1.21.1
62	     */
63	    public static <T extends Node> Stream<T> streamNodes(Evaluator evaluator, Element root, Class<T> type) {
64	        evaluator.reset();
65	        return root.nodeStream(type).filter(evaluator.asNodePredicate(root));
66	    }
67	
68	    /**
69	     Finds the first Element that matches the Evaluator that descends from the root, and stops the query once that first
70	     match is found.
71	     @param eval Evaluator to test elements against
72	     @param root root of tree to descend
73	     @return the first match; {@code null} if none
74	     */
75	    public static @Nullable Element findFirst(Evaluator eval, Element root) {
76	        Element el = stream(eval, root).findFirst().orElse(null);
77	        eval.reset();
78	        return el;
79	    }
80	
81	    /**
82	     Finds the first Node that matches the Evaluator that descends from the root, and stops the query once that first
83	     match is found.
84	
85	     @param eval Evaluator to test elements against
86	     @param root root of tree to descend
87	     @param type the type of node to collect (e.g. {@link Element}, {@link LeafNode}, {@link TextNode} etc)
88	     @return the first match; {@code null} if none
89	     @since 1.21.1
90	     */
91	    public static <T extends Node> @Nullable T findFirstNode(Evaluator eval, Element root, Class<T> type) {
92	        T node = streamNodes(eval, root, type).findFirst().orElse(null);
93	        eval.reset();
94	        return node;
95	    }
96	
97	    /**
98	     Build a list of nodes that match the supplied criteria, by visiting the root and every descendant of root, and
99	     testing it against the Evaluator.
100	
101	     @param evaluator Evaluator to test elements against
102	     @param root root of tree to descend
103	     @param type the type of node to collect (e.g. {@link Element}, {@link LeafNode}, {@link TextNode} etc)
104	     @param <T> the type of node to collect
105	     @return list of matches; empty if none
106	     */
107	    public static <T extends Node> Nodes<T> collectNodes(Evaluator evaluator, Element root, Class<T> type) {
108	        return streamNodes(evaluator, root, type).collect(toCollection(Nodes::new));
109	    }
110	}
