3	import org.jsoup.internal.SoftPool;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Element;
6	import org.jsoup.nodes.LeafNode;
7	import org.jsoup.nodes.Node;
8	import org.jsoup.nodes.NodeIterator;
9	import org.jsoup.nodes.TextNode;
10	
11	import java.util.ArrayList;
12	import java.util.Collections;
13	import java.util.List;
14	import java.util.Map;
15	import java.util.WeakHashMap;
16	
17	/**
18	 * Base structural evaluator.
19	 */
20	abstract class StructuralEvaluator extends Evaluator {
21	    final Evaluator evaluator;
22	    boolean wantsNodes; // if the evaluator requested nodes, not just elements
23	
24	    public StructuralEvaluator(Evaluator evaluator) {
25	        this.evaluator = evaluator;
26	        wantsNodes = evaluator.wantsNodes();
27	    }
28	
29	    @Override
30	    boolean wantsNodes() {
31	        return wantsNodes;
32	    }
33	
34	    // Memoize inner matches, to save repeated re-evaluations of parent, sibling etc.
35	    // root + element: Boolean matches. ThreadLocal in case the Evaluator is compiled then reused across multi threads
36	    final ThreadLocal<Map<Node, Map<Node, Boolean>>> threadMemo = ThreadLocal.withInitial(WeakHashMap::new);
37	
38	    boolean memoMatches(final Element root, final Node node) {
39	        Map<Node, Map<Node, Boolean>> rootMemo = threadMemo.get();
40	        Map<Node, Boolean> memo = rootMemo.computeIfAbsent(root, r -> new WeakHashMap<>());
41	        return memo.computeIfAbsent(node, test -> evaluator.matches(root, test));
42	    }
43	
44	    @Override protected void reset() {
45	        threadMemo.remove();
46	        evaluator.reset();
47	        super.reset();
48	    }
49	
50	    @Override
51	    public boolean matches(Element root, Element element) {
52	        return evaluateMatch(root, element);
53	    }
54	
55	    @Override
56	    boolean matches(Element root, LeafNode leafNode) {
57	        return evaluateMatch(root, leafNode);
58	    }
59	
60	    abstract boolean evaluateMatch(Element root, Node node);
61	
62	    static class Root extends Evaluator {
63	        @Override
64	        public boolean matches(Element root, Element element) {
65	            return root == element;
66	        }
67	
68	        @Override protected int cost() {
69	            return 1;
70	        }
71	
72	        @Override public String toString() {
73	            return ">";
74	        }
75	    }
76	
77	    /** The explicit :scope pseudo-class; matches the element the (sub-)query is anchored to. Equivalent to the
78	     implicit Root that a leading combinator applies to. */
79	    static class Scope extends Evaluator {
80	        @Override
81	        public boolean matches(Element root, Element element) {
82	            return root == element;
83	        }
84	
85	        @Override protected int cost() {
86	            return 1;
87	        }
88	
89	        @Override public String toString() {
90	            return ":scope";
91	        }
92	    }
93	
94	    static class Has extends StructuralEvaluator {
95	        static final SoftPool<NodeIterator<Node>> NodeIterPool =
96	            new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class));
97	        // the element here is just a placeholder so this can be final - gets set in restart()
98	
99	        private final List<Evaluator> branches; // the top-level (comma separated) relative selectors
100	        private final boolean[] wantsSiblings; // per branch: if anchored to the scope by a leading + or ~ combinator
101	        private final boolean[] nodeChains; // per branch: if the chain matches leaf nodes (::comment, ::text etc)
102	
103	        public Has(Evaluator evaluator) {
104	            super(evaluator);
105	            // Split the selector group into its top-level branches, so that each can be tested against the correct
106	            // candidate set (the scope element's descendants, or its following siblings)
107	            if (evaluator instanceof CombiningEvaluator.Or)
108	                branches = ((CombiningEvaluator.Or) evaluator).evaluators;
109	            else
110	                branches = Collections.singletonList(evaluator);
111	            wantsSiblings = new boolean[branches.size()];
112	            nodeChains = new boolean[branches.size()];
113	            for (int i = 0; i < branches.size(); i++) {
114	                Evaluator branch = branches.get(i);
115	                wantsSiblings[i] = anchoredToFollowingSiblings(branch);
116	                nodeChains[i] = chainContainsLeaf(branch);
117	                if (nodeChains[i])
118	                    forceNodeAdjacency(branch); // a leaf in the chain makes every + step compare the full node sequence
119	            }
120	        }
121	
122	        @Override public boolean matches(Element root, Element element) {
123	            // we want to minimize GCs so reusing the Iterator obj
124	            NodeIterator<Node> it = NodeIterPool.borrow();
125	            try {
126	                for (int i = 0; i < branches.size(); i++) {
127	                    Evaluator branch = branches.get(i);
128	                    if (wantsSiblings[i]) {
129	                        // a leading + or ~ combinator anchors the branch to the element's following siblings (and their
130	                        // descendants); only these branches may see outside the element's own subtree
131	                        if (nodeChains[i]) {
132	                            // the chain matches leaf nodes (text, comments, etc), so those are candidates too and the
133	                            // siblings are walked as the complete node sequence rather than the element sequence
134	                            for (Node sib = element.nextSibling(); sib != null; sib = sib.nextSibling()) {
135	                                it.restart(sib);
136	                                while (it.hasNext()) {
137	                                    if (branch.matches(element, it.next()))
138	                                        return true;
139	                                }
140	                            }
141	                        } else {
142	                            for (Element sib = element.nextElementSibling(); sib != null; sib = sib.nextElementSibling()) {
143	                                it.restart(sib);
144	                                while (it.hasNext()) {
145	                                    if (branch.matches(element, it.next()))
146	                                        return true;
147	                                }
148	                            }
149	                        }
150	                    } else {
151	                        // otherwise we only want to match children (or below), and not the input element
152	                        it.restart(element);
153	                        while (it.hasNext()) {
154	                            Node node = it.next();
155	                            if (node == element) continue; // don't match self, only descendants
156	                            if (branch.matches(element, node))
157	                                return true;
158	                        }
159	                    }
160	                }
161	            } finally {
162	                NodeIterPool.release(it);
163	            }
164	            return false;
165	        }
166	
167	        @Override
168	        boolean evaluateMatch(Element root, Node node) {
169	            return false; // unused; :has(::comment)) goes via implicit root combinator
170	        }
171	
172	        /* Test if a :has branch is anchored to the scope root by a leading + or ~ combinator (a PreviousSibling or
173	         ImmediatePreviousSibling whose left side is the Root / :scope anchor). Only such a branch is evaluated against
174	         the scope element's siblings; others see its descendants only, so that e.g. :has(h1 ~ h2) cannot match elements
175	         outside the scope's subtree. The :is(), :not(), and nested :has() containers establish their own anchor and do
176	         not borrow the outer sibling relation, so traversal stops at them; a later + or ~ within the branch, such as
177	         "> p + x", is an internal combinator and is not mistaken for the anchor either. */
178	        private static boolean anchoredToFollowingSiblings(Evaluator eval) {
179	            if (eval instanceof PreviousSibling || eval instanceof ImmediatePreviousSibling) {
180	                Evaluator left = ((StructuralEvaluator) eval).evaluator;
181	                if (isScopeAnchor(left))
182	                    return true;
183	                return anchoredToFollowingSiblings(left);
184	            }
185	            if (eval instanceof CombiningEvaluator) {
186	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators) {
187	                    if (anchoredToFollowingSiblings(inner))
188	                        return true;
189	                }
190	            } else if (eval instanceof ImmediateParentRun) {
191	                for (Evaluator inner : ((ImmediateParentRun) eval).evaluators) {
192	                    if (anchoredToFollowingSiblings(inner))
193	                        return true;
194	                }
195	            } else if (eval instanceof Ancestor) {
196	                return anchoredToFollowingSiblings(((StructuralEvaluator) eval).evaluator);
197	            }
198	            return false; // Is, Not, Has (own anchors), and leaf / simple evaluators
199	        }
200	
201	        /* The implicit Root of a leading combinator, or an explicit :scope, possibly compounded with simple filters
202	         (e.g. :scope:not(.x)). Must not descend into structural evaluators, where the scope is only a deeper operand. */
203	        private static boolean isScopeAnchor(Evaluator eval) {
204	            if (eval instanceof Root || eval instanceof Scope)
205	                return true;
206	            if (eval instanceof CombiningEvaluator) {
207	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators) {
208	                    if (isScopeAnchor(inner))
209	                        return true;
210	                }
211	            }
212	            return false;
213	        }
214	
215	        /* Test if the branch's chain contains a leaf-node selector (::comment, ::text, etc). A nested :has() is its own
216	         chain anchored to its own scope, so it is not considered; :is() and :not() contents still qualify candidates of
217	         this chain, and are descended into. */
218	        private static boolean chainContainsLeaf(Evaluator eval) {
219	            if (eval instanceof Has)
220	                return false; // a nested :has() runs its own chain
221	            if (eval instanceof NodeEvaluator)
222	                return true;
223	            if (eval instanceof CombiningEvaluator) {
224	                for (Evaluator inner : ((CombiningEvaluator) eval).evaluators) {
225	                    if (chainContainsLeaf(inner))
226	                        return true;
227	                }
228	            } else if (eval instanceof ImmediateParentRun) {
229	                for (Evaluator inner : ((ImmediateParentRun) eval).evaluators) {
230	                    if (chainContainsLeaf(inner))
231	                        return true;
232	                }
233	            } else if (eval instanceof StructuralEvaluator) {
234	                return chainContainsLeaf(((StructuralEvaluator) eval).evaluator);
235	            }
236	            return false;
237	        }
238	
239	        /* Once a chain contains a leaf-node selector, an adjacent-sibling (+) step compares against the complete
240	         sibling sequence when a leaf selector lies immediately on either side of that step: text, comment, and data
241	         leaves then count as intervening nodes instead of being skipped. The leading + (or ~) step anchored directly to
242	         the :scope element keeps ordinary element adjacency -- a leaf reached later in the chain (e.g. the comment in
243	         "+ div ::comment") must not tighten that first step, and each nested layer narrows independently. A nested
244	         :has() runs its own chain (prepared by its own constructor); :is() and :not() contents are chains of their own
245	         and determine their mode from their own contents. */
246	        private static void forceNodeAdjacency(Evaluator eval) {
247	            applyNodeAdjacency(eval, true); // the first structural step of a branch is anchored to the :scope
248	        }
249	
250	        private static void applyNodeAdjacency(Evaluator eval, boolean leadingScope) {
251	            if (eval instanceof Has)
252	                return; // a nested :has() runs its own chain
253	            if (eval instanceof Is || eval instanceof Not) {
254	                // the container's contents are their own selector list / chain, anchored afresh
255	                applyNodeAdjacency(((StructuralEvaluator) eval).evaluator, false);
256	                return;
257	            }
258	            if (eval instanceof CombiningEvaluator.And) {
259	                ArrayList<Evaluator> members = ((CombiningEvaluator.And) eval).evaluators;
260	                for (Evaluator member : members)
261	                    applyNodeAdjacency(member, leadingScope);
262	                for (int i = 0; i < members.size(); i++) {
263	                    Evaluator member = members.get(i);
264	                    if (!(member instanceof ImmediatePreviousSibling))
265	                        continue;
266	                    ImmediatePreviousSibling ips = (ImmediatePreviousSibling) member;
267	                    boolean nodeAdjacent = chainContainsLeaf(ips.evaluator); // a leaf earlier in the chain
268	                    if (!nodeAdjacent && !(leadingScope && isScopeAnchor(ips.evaluator))) {
269	                        for (int j = 0; j < members.size(); j++) {
270	                            if (j != i && chainContainsLeaf(members.get(j))) {
271	                                nodeAdjacent = true; // a leaf in the right-hand compound
272	                                break;
273	                            }
274	                        }
275	                    }
276	                    if (nodeAdjacent)
277	                        ips.wantsNodes = true;
278	                }
279	                return;
280	            }
281	            if (eval instanceof CombiningEvaluator.Or) {
282	                for (Evaluator branch : ((CombiningEvaluator.Or) eval).evaluators)
283	                    applyNodeAdjacency(branch, false); // each alternative is its own chain
284	                return;
285	            }
286	            if (eval instanceof ImmediateParentRun) {
287	                for (Evaluator inner : ((ImmediateParentRun) eval).evaluators)
288	                    applyNodeAdjacency(inner, leadingScope);
289	                return;
290	            }
291	            if (eval instanceof StructuralEvaluator) {
292	                // descend the left-hand structural chain (Ancestor, PreviousSibling, ImmediatePreviousSibling);
293	                // only the outermost step carries the leading scope anchor
294	                applyNodeAdjacency(((StructuralEvaluator) eval).evaluator, false);
295	            }
296	        }
297	
298	        @Override protected int cost() {
299	            return 10 * evaluator.cost();
300	        }
301	
302	        @Override
303	        public String toString() {
304	            return String.format(":has(%s)", evaluator);
305	        }
306	    }
307	
308	    /** Implements the :is(sub-query) pseudo-selector */
309	    static class Is extends StructuralEvaluator {
310	        public Is(Evaluator evaluator) {
311	            super(evaluator);
312	        }
313	
314	        @Override
315	        boolean evaluateMatch(Element root, Node node) {
316	            return evaluator.matches(root, node);
317	        }
318	
319	        @Override protected int cost() {
320	            return 2 + evaluator.cost();
321	        }
322	
323	        @Override
324	        public String toString() {
325	            return String.format(":is(%s)", evaluator);
326	        }
327	    }
328	
329	    static class Not extends StructuralEvaluator {
330	        public Not(Evaluator evaluator) {
331	            super(evaluator);
332	        }
333	
334	        @Override
335	        boolean evaluateMatch(Element root, Node node) {
336	            return !memoMatches(root, node);
337	        }
338	
339	        @Override protected int cost() {
340	            return 2 + evaluator.cost();
341	        }
342	
343	        @Override
344	        public String toString() {
345	            return String.format(":not(%s)", evaluator);
346	        }
347	    }
348	
349	    /**
350	     Any Ancestor (i.e., ascending parent chain.).
351	     */
352	    static class Ancestor extends StructuralEvaluator {
353	        boolean strictRoot; // when true, the leftmost compound may match a strict descendant of root only -- it cannot
354	                            // match the :has() scope element itself (an implicit ":scope " relative anchor)
355	
356	        public Ancestor(Evaluator evaluator) {
357	            super(evaluator);
358	        }
359	
360	        @Override
361	        boolean evaluateMatch(Element root, Node node) {
362	            if (root == node)
363	                return false;
364	
365	            for (Node parent = node.parent(); parent != null; parent = parent.parent()) {
366	                if (memoMatches(root, parent)) {
367	                    if (strictRoot && parent == root)
368	                        return false; // the scope element itself cannot be the leftmost relative match
369	                    return true;
370	                }
371	                if (parent == root)
372	                    break;
373	            }
374	            return false;
375	        }
376	
377	        @Override
378	        protected int cost() {
379	            return 8 * evaluator.cost(); // probably lower than has(), but still significant, depending on doc and el depth.
380	        }
381	
382	        @Override
383	        public String toString() {
384	            return String.format("%s ", evaluator);
385	        }
386	    }
387	
388	    /**
389	     Holds a list of evaluators for one > two > three immediate parent matches, and the final direct evaluator under
390	     test. To match, these are effectively ANDed together, starting from the last, matching up to the first.
391	     */
392	    static class ImmediateParentRun extends StructuralEvaluator {
393	        final ArrayList<Evaluator> evaluators = new ArrayList<>();
394	        int cost = 2;
395	        boolean strictRoot; // when true, the leftmost step may not land on the :has() scope element itself
396	
397	        public ImmediateParentRun(Evaluator evaluator) {
398	            super(evaluator);
399	            evaluators.add(evaluator);
400	            cost += evaluator.cost();
401	        }
402	
