	assertEquals(ids(doc, "#s>:nth-child(2 of b, i)"), "y");
	// whitespace inside the parens is fine
	assertEquals("z", doc.selectFirst("#s>:nth-child( 2 of b )").id());
	assertEquals("w", doc.selectFirst("#s>:nth-last-child(1 of b , i)").id());
