	assertEquals("y", doc.selectFirst("#s>:nth-child(1 of i)").id());
	assertTrue(doc.select("#s>:nth-child(2 of i)").isEmpty());
	assertTrue(doc.select("#s>:nth-child(2 of em)").isEmpty()); // em is 4th of all, no 2nd em
