import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Selector;

import java.util.List;

public class ScratchVerify {
    static int failures = 0;

    static void check(boolean cond, String msg) {
        if (!cond) { failures++; System.out.println("FAIL: " + msg); }
        else System.out.println("ok:   " + msg);
    }

    static void eq(Object actual, Object expected, String msg) {
        boolean ok = (expected == null) ? actual == null : expected.equals(actual);
        if (!ok) {
            failures++;
            System.out.println("FAIL: " + msg + "\n      expected=[" + expected + "]\n      actual  =[" + actual + "]");
        } else System.out.println("ok:   " + msg + "  -> " + actual);
    }

    static void expectThrow(String css, String msg) {
        try {
            QueryParser.parse(css);
            failures++;
            System.out.println("FAIL: " + msg + " (no exception for: " + css + ")");
        } catch (Selector.SelectorParseException e) {
            System.out.println("ok:   " + msg + "  -> " + e.getMessage().replaceAll("\n", " "));
        }
    }

    static String ids(Document doc, String css) {
        return String.join(",", doc.select(css).eachAttr("id"));
    }

    static List<String> sig(Document d, String css) {
        Elements els = d.select(css);
        java.util.ArrayList<String> out = new java.util.ArrayList<>();
        for (Element e : els) out.add(e.tagName() + "#" + e.id() + ":" + e.text()
            + ":parent=" + e.parent().id());
        return out;
    }

    public static void main(String[] args) {
        // ---- fixture: x b, y i, z b, em(no id), w b ----
        Document doc = Jsoup.parse(
            "<div id=s><b id=x class='c1'>a</b><i id=y>b</i><b id=z class='c2'>c</b><em>d</em><b id=w>e</b></div>");

        // 1. basic of-filter counting, document order
        eq(ids(doc, "#s>:nth-child(1 of b)"), "x", "1st b is x");
        eq(ids(doc, "#s>:nth-child(2 of b)"), "z", "2nd b is z");
        eq(ids(doc, "#s>:nth-child(3 of b)"), "w", "3rd b is w");
        eq(ids(doc, "#s>:nth-child(4 of b)"), "", "no 4th b");
        eq(ids(doc, "#s>:nth-child(odd of b)"), "x,w", "odd b");
        eq(ids(doc, "#s>:nth-child(even of b)"), "z", "even b");
        eq(ids(doc, "#s>:nth-child(-n+2 of b)"), "x,z", "negative step -n+2");
        eq(ids(doc, "#s>:nth-child(0n+1 of b)"), "x", "zero step 0n+1");
        eq(ids(doc, "#s>:nth-child(0 of b)"), "", "0 never matches");
        eq(ids(doc, "#s>:nth-child(2n of b)"), "z", "2n b");

        // 2. nth-last-child
        eq(ids(doc, "#s>:nth-last-child(1 of b)"), "w", "last b");
        eq(ids(doc, "#s>:nth-last-child(2 of b)"), "z", "2nd last b");
        eq(ids(doc, "#s>:nth-last-child(odd of b)"), "w,z", "odd from end");
        eq(ids(doc, "#s>:nth-last-child(-n+2 of b)"), "z,w", "-n+2 from end");

        // 3. candidate must itself match S
        eq(doc.selectFirst("#s>:nth-child(2 of b)").tagName(), "b", "result element is b");
        eq(ids(doc, "#s>:nth-child(1 of i)"), "y", "i at its own filtered index");
        eq(ids(doc, "#s>:nth-child(2 of i)"), "", "no 2nd i");

        // 4. S selector list, duplicate branches count once
        eq(ids(doc, "#s>:nth-child(2 of b, i)"), "y", "list b,i: 2nd is y(i)");
        eq(ids(doc, "#s>:nth-child(2 of b,b)"), "z", "duplicate branch b,b counts once");
        eq(ids(doc, "#s>:nth-child(3 of b, b)"), "w", "dup branch no inflation");
        eq(ids(doc, "#s>:nth-last-child(1 of b , i)"), "w", "ws around inner comma");

        // 5. class / attribute / :not / nested pseudo against parsed DOM
        eq(ids(doc, "#s>:nth-child(1 of b.c1)"), "x", "class in S");
        eq(ids(doc, "#s>:nth-child(2 of b.c1)"), "", "only one b.c1");
        eq(ids(doc, "#s>:nth-child(1 of b:not(.c2))"), "x", ":not in S");
        eq(ids(doc, "#s>:nth-child(2 of b:not(.c2))"), "w", "2nd non-c2 b");
        eq(ids(doc, "#s>:nth-child(1 of [class])"), "x", "attribute presence in S");
        eq(ids(doc, "#s>:nth-child(2 of [class])"), "z", "2nd with class");
        eq(ids(doc, "#s>:nth-child(1 of b:is(.c1))"), "x", ":is nested pseudo");
        eq(ids(doc, "#s>:nth-child(2 of b:nth-child(odd))"), "z", "nested nth-child in S");

        // 6. combinators in S
        Document doc2 = Jsoup.parse(
            "<body><div id=p1><b id=a1><span></span></b><i></i><b id=a2></b></div>" +
            "<div id=p2><b id=b1></b><b id=b2><span></span></b></div></body>");
        eq(ids(doc2, "div>:nth-child(1 of div > b)"), "a1,b1", "child combinator S, per parent");
        eq(ids(doc2, ":nth-child(1 of body b)"), "a1,b1", "descendant combinator S");
        eq(ids(doc2, ":nth-child(2 of body b)"), "a2,b2", "descendant combinator S 2");
        eq(ids(doc2, ":nth-child(1 of b:has(span))"), "a1,b2", ":has() nested in S");
        eq(ids(doc2, ":nth-child(1 of i + b)"), "a2", "adjacent sibling combinator in S");
        eq(ids(doc2, ":nth-child(1 of i ~ b)"), "a2", "general sibling combinator in S");

        // 7. outer comma vs inner comma layering
        eq(ids(doc, "#s>b:nth-child(1 of i), #s>i:nth-child(1 of b)"), "y",
            "outer comma: b-of-i (none) or i-of-b (y)");
        eq(ids(doc, "#s>:nth-child(1 of b), #s>:nth-last-child(1 of b)"), "x,w",
            "two outer branches");

        // 8. dedup + document order when branches overlap
        eq(ids(doc, "#s>:nth-child(1 of b), #s>b"), "x,z,w", "overlap dedup, doc order");
        eq(ids(doc, "#s>b, #s>:nth-child(2 of b)"), "x,z,w", "overlap dedup reversed order");

        // 9. quotes / parens / escapes / whitespace don't split wrongly
        Document doc3 = Jsoup.parse(
            "<div id=q><b id=q1 data-x='of b'></b><i id=q2 title='a, b (c)'></i><b class='a,b' id=q3></b></div>");
        eq(ids(doc3, "#q>:nth-child(1 of [id], [data-x='of b'])"), "q1", "'of b' inside quoted attr value");
        eq(ids(doc3, "#q>:nth-child(2 of [data-x='of b'], i)"), "q2", "quoted value + inner comma");
        eq(ids(doc3, "#q>:nth-child(1 of [title='a, b (c)'])"), "q2", "comma/parens inside quoted value");
        eq(ids(doc3, "#q>:nth-child(1 of .a\\,b)"), "q3", "escaped comma in class");
        eq(ids(doc3, "#q>:nth-child(\n 1\tof\r b )"), "q1", "tabs/newlines as whitespace");

        // 10. no-of backwards compatibility
        Document doc4 = Jsoup.parse("<div id=p><b id=1></b><i id=2></i><b id=3></b><b id=4></b></div>");
        eq(ids(doc4, "#p>:nth-child(2)"), "2", "plain nth-child unchanged");
        eq(ids(doc4, "#p>:nth-last-child(1)"), "4", "plain nth-last-child unchanged");
        eq(ids(doc4, "#p>:nth-child(odd)"), "1,3", "plain odd unchanged");
        eq(ids(doc4, "b:nth-child(odd)"), "1,3", "tag+nth unchanged");
        eq(ids(doc4, "[id]:nth-child(even)"), "2,4", "attr+nth unchanged");
        eq(ids(doc4, "#p>:nth-of-type(2)"), "3", "nth-of-type unchanged");

        // 11. per-parent counting restart; document scope
        eq(ids(doc2, ":nth-child(1 of b)"), "a1,b1", "counting restarts per parent");
        eq(ids(doc2, ":nth-last-child(1 of b)"), "a2,b2", "last per parent");

        // 12. error cases -> SelectorParseException, no degraded behavior
        expectThrow(":nth-child(2 of )", "empty S");
        expectThrow(":nth-child(2 of)", "empty S no space");
        expectThrow(":nth-child(2 of b", "unbalanced open paren");
        expectThrow(":nth-child(2 of b))", "extra close paren");
        expectThrow(":nth-child(of b)", "missing position expr");
        expectThrow(":nth-child()", "empty args");
        expectThrow(":nth-child(foo of b)", "illegal position symbol");
        expectThrow(":nth-child(2x of b)", "garbage after step");
        expectThrow(":nth-child(2 of b >)", "combinator no RHS (child)");
        expectThrow(":nth-child(2 of b +)", "combinator no RHS (adjacent)");
        expectThrow(":nth-child(2 of b ~)", "combinator no RHS (sibling)");
        expectThrow(":nth-child(2 of ,b)", "leading comma in S");
        expectThrow(":nth-child(2 of b,)", "trailing comma in S");
        expectThrow(":nth-child(2 of b,,i)", "double comma in S");
        expectThrow(":nth-of-type(2 of b)", "of S rejected for nth-of-type");
        expectThrow(":nth-last-of-type(2 of b)", "of S rejected for nth-last-of-type");
        expectThrow("b:nth-child(2 of b,", "unterminated outer list after valid of");
        expectThrow(":nth-child(2 of b :foo())", "unknown nested pseudo");

        // 13. document remains usable after parse failure
        String beforeHtml = doc.html();
        try { doc.select(":nth-child(2 of b >)"); }
        catch (Selector.SelectorParseException ignored) {}
        eq(doc.html(), beforeHtml, "HTML unchanged after failed parse");
        eq(ids(doc, "#s>:nth-child(2 of b)"), "z", "select works after failure");
        eq(doc.selectFirst("#x").text(), "a", "traversal works after failure");
        int childCount = doc.selectFirst("#s").childrenSize();
        doc.select("#s>:nth-child(odd of b)");
        doc.select(":nth-child(2 of b, i)");
        eq(doc.selectFirst("#s").childrenSize(), childCount, "no nodes created/deleted");
        eq(doc.html(), beforeHtml, "HTML unchanged after successful selects");

        // 14. serialize -> reparse equivalence
        Document reparsed = Jsoup.parse(doc.html());
        String css = "#s>:nth-child(odd of b), #s>:nth-last-child(2 of b)";
        eq(sig(reparsed, css).toString(), sig(doc, css).toString(),
            "reparse: equivalent elements/text/hierarchy/order/dedup");
        eq(String.join(",", reparsed.select(css).eachAttr("id")),
           String.join(",", doc.select(css).eachAttr("id")), "reparse: same ids/order");

        // 15. evaluator reuse across different docs - no shared state
        Evaluator compiled = QueryParser.parse(":nth-child(1 of b)");
        Document dA = Jsoup.parse("<div><b id=a1></b><b id=a2></b></div>");
        Document dB = Jsoup.parse("<div><i></i><b id=b1></b><b id=b2></b></div>");
        eq(String.join(",", dA.select(compiled).eachAttr("id")), "a1", "reused eval doc A first run");
        eq(String.join(",", dB.select(compiled).eachAttr("id")), "b1", "reused eval doc B (filtered pos, not DOM index)");
        eq(String.join(",", dA.select(compiled).eachAttr("id")), "a1", "reused eval doc A again after B");
        eq(String.join(",", dB.select(compiled).eachAttr("id")), "b1", "reused eval doc B again");
        eq(String.join(",", dA.select(":nth-child(1 of b)").eachAttr("id")), "a1", "fresh parse A");
        eq(String.join(",", dB.select(":nth-child(1 of b)").eachAttr("id")), "b1", "fresh parse B");

        // 16. empty doc / no match
        Document empty = Jsoup.parse("");
        eq(empty.select(":nth-child(1 of b)").size(), 0, "empty doc -> empty result");
        eq(empty.selectFirst(":nth-child(1 of b)"), null, "empty doc selectFirst null");
        eq(doc.select(":nth-child(99 of b)").size(), 0, "no match -> empty");
        eq(doc.select("table>:nth-child(1 of tr)").size(), 0, "absent subtree -> empty");

        // 17. nested of-in-of and selector round trip
        Document doc5 = Jsoup.parse("<div><b id=1></b><b id=2></b><b id=3></b></div>");
        eq(ids(doc5, ":nth-child(1 of b:nth-child(odd of b))"), "1", "nested of-in-of");
        String roundTrip = ":nth-child(2n+1 of b, i)";
        eq(QueryParser.parse(roundTrip).toString(), ":nth-child(2n+1 of b, i)", "toString round trip");

        // 18. root element itself is not a filtered child
        Document doc6 = Jsoup.parse("<b id=rootcase></b>");
        eq(doc6.select("html:nth-child(1 of body)").size(), 0, "html does not match as filtered child");

        System.out.println();
        if (failures == 0) System.out.println("ALL CHECKS PASSED");
        else { System.out.println(failures + " CHECK(S) FAILED"); System.exit(1); }
    }
}

